# Cloudflare Pages / Netlify — plik public/_redirects (trafia do dist/)
/api/*   https://api.devdesk.pl/api/:splat   200
/*       /index.html                          200

# Cloudflare Pages / Netlify — plik public/_headers
/assets/*
  Cache-Control: public, max-age=31536000, immutable
/index.html
  Cache-Control: no-cache
/*
  X-Content-Type-Options: nosniff
  Referrer-Policy: strict-origin-when-cross-origin

# Vercel — plik vercel.json w katalogu projektu
{
  "rewrites": [{ "source": "/((?!api/).*)", "destination": "/index.html" }],
  "headers": [
    { "source": "/assets/(.*)", "headers": [{ "key": "Cache-Control", "value": "public, max-age=31536000, immutable" }] }
  ]
}

// app/handleChunkErrors.js
const RELOAD_KEY = 'devdesk:chunk-reload';

export function handleChunkErrors() {
  window.addEventListener('vite:preloadError', (event) => {
    const lastReload = Number(sessionStorage.getItem(RELOAD_KEY) ?? 0);
    if (Date.now() - lastReload < 10_000) return; // przeładowano przed chwilą — pozwól zadziałać granicy błędu
    event.preventDefault();
    sessionStorage.setItem(RELOAD_KEY, String(Date.now()));
    window.location.reload();
  });
}

