// app/NewVersionBanner.tsx
import { useEffect, useState } from 'react';

const CURRENT = import.meta.env.VITE_APP_VERSION;

export function NewVersionBanner() {
  const [available, setAvailable] = useState(false);

  useEffect(() => {
    if (!CURRENT) return;
    const id = setInterval(async () => {
      try {
        const res = await fetch('/version.json', { cache: 'no-store' });
        const { version } = (await res.json()) as { version: string };
        if (version !== CURRENT) setAvailable(true);
      } catch {
        // brak sieci — spróbujemy przy następnym sprawdzeniu
      }
    }, 5 * 60_000);
    return () => clearInterval(id);
  }, []);

  if (!available) return null;
  return (
    <div role="status" className="banner">
      Dostępna jest nowa wersja DevDesk.
      <button type="button" onClick={() => window.location.reload()}>Odśwież</button>
    </div>
  );
}
